  'Ask a question. DEIXIS finds publications, lets you choose the sources, and links each claim to a passage you can open.': 'Bir soru sorun. DEIXIS yayınları bulur, kaynakları seçmenize olanak tanır ve her iddiayı açıp okuyabileceğiniz bir pasaja bağlar.',
