  'Writes the answer from the passages of the sources you include, linking each claim to its passage.': 'Dahil ettiğiniz kaynakların pasajlarından yanıtı yazar ve her iddiayı kendi pasajına bağlar.',
  'Plans the searches in the scholarly providers and proposes which results to include. You make the final selection.': 'Akademik sağlayıcılardaki aramaları planlar ve hangi sonuçların dahil edileceğini önerir. Son seçimi siz yaparsınız.',
  'When an answer is ready, checks each claim against the passages it cites. It never changes the answer and is not independent verification.': 'Yanıt hazır olduğunda her iddiayı atıf yaptığı pasajlarla karşılaştırır. Yanıtı asla değiştirmez ve bağımsız doğrulama değildir.',
