  'You paused this run.': 'Bu işlemi siz duraklattınız.',
  'DEIXIS was closed while this run was working. Completed steps are kept; resuming may repeat an unfinished search or model call.': 'Bu işlem çalışırken DEIXIS kapatıldı. Tamamlanan adımlar korunur; devam etmek yarım kalan bir aramayı veya model çağrısını tekrarlayabilir.',
  'The selected model connection is not ready. Nothing was sent to another model.': 'Seçilen model bağlantısı hazır değil. Başka bir modele hiçbir şey gönderilmedi.',
  'The selected model connection is not available. Nothing was sent to another model.': 'Seçilen model bağlantısı kullanılamıyor. Başka bir modele hiçbir şey gönderilmedi.',
  'Open Settings, connect it again, then resume this run.': 'Ayarlar’ı açıp bağlantıyı yeniden kurun, sonra bu işlemi sürdürün.',
  'The model call did not complete. Completed work is saved.': 'Model çağrısı tamamlanmadı. Tamamlanan iş kaydedildi.',
  'The model did not answer before the reading time ran out; this work counts as not read in time.': 'Model okuma süresi dolmadan yanıt vermedi; bu makale zamanında okunmamış sayılır.',
  'The model session reported tool use or loaded instructions, so its output was rejected.': 'Model oturumu araç kullanımı veya yüklenmiş talimat bildirdiği için çıktısı reddedildi.',
  'A scholarly provider rate-limited a search. Completed searches are kept; no other provider was used in its place.': 'Bir akademik sağlayıcı bir aramaya hız sınırı uyguladı. Tamamlanan aramalar korunur; yerine başka sağlayıcı kullanılmadı.',
  'A scholarly provider exhausted its quota. Completed searches are kept; no other provider was used in its place. This run will not retry it automatically; resuming or retrying allows another attempt.': 'Bir akademik sağlayıcının kotası tükendi. Tamamlanan aramalar korunur; yerine başka sağlayıcı kullanılmadı. Bu koşuda otomatik yeniden deneme yapılmaz; sürdürme veya yeniden deneme yeni bir isteğe izin verir.',
  'A scholarly provider has no configured key, so its search was not sent. Completed searches are kept; no other provider was used in its place.': 'Bir akademik sağlayıcının yapılandırılmış anahtarı yok, bu nedenle araması gönderilmedi. Tamamlanan aramalar korunur; yerine başka sağlayıcı kullanılmadı.',
  'The connector version recorded for earlier pages changed or could not be read, so this search cannot continue. Completed searches are kept; no other provider was used in its place.': 'Önceki sayfalar için kaydedilen bağlayıcı sürümü değişti veya okunamadı, bu nedenle bu arama sürdürülemiyor. Tamamlanan aramalar korunur; yerine başka sağlayıcı kullanılmadı.',
  'A scholarly provider requires authentication for this search.': 'Bir akademik sağlayıcı bu arama için kimlik doğrulaması istiyor.',
  'A scholarly provider did not accept the configured key.': 'Bir akademik sağlayıcı yapılandırılan anahtarı kabul etmedi.',
  'A scholarly provider did not answer in time. Whether the search was processed is unknown.': 'Bir akademik sağlayıcı zamanında yanıt vermedi. Aramanın işlenip işlenmediği bilinmiyor.',
  'A scholarly provider search failed.': 'Bir akademik sağlayıcı araması başarısız oldu.',
  'A scholarly provider returned a response DEIXIS could not read.': 'Bir akademik sağlayıcı DEIXIS’in okuyamadığı bir yanıt döndürdü.',
  'This run reached its call budget.': 'Bu işlem çağrı bütçesine ulaştı.',
  'The model output failed validation after one repair attempt.': 'Model çıktısı bir onarım denemesinden sonra doğrulamayı geçemedi.',
  'No source is included.': 'Dahil edilen kaynak yok.',
  'An internal error stopped the run.': 'Bir iç hata işlemi durdurdu.',
