  'Citation chaining': 'Atıf zinciri',
  'OpenAlex only. While the search runs, OpenAlex is asked for the works that the first {seeds} works of its semantic search cite, and for the works that cite them; when that search gives fewer works, the ranking fills the list. Works you verified are not used as seeds. A new work is kept when a setting or task term stands in its title or abstract and its reply arrives a few seconds before the ranking stage ends; the run says how many seeds it used once the search is done.': 'Yalnız OpenAlex. Arama sürerken OpenAlex\'e, kendi anlamsal aramasının ilk {seeds} eserinin atıf yaptığı eserler ile bunlara atıf yapan eserler sorulur; bu arama daha az eser verirse liste sıralamadan tamamlanır. Doğruladığınız eserler tohum olarak kullanılmaz. Yeni bir eser, başlığında ya da özetinde bir bağlam ya da görev terimi geçiyorsa ve yanıtı sıralama aşaması bitmeden birkaç saniye önce gelmişse tutulur; koşu, arama bittikten sonra kaç tohum kullandığını gösterir.',
  'Up to {backward} reference requests and {forward} citing requests · up to {cap} citing works per request · at most {attempts} attempts with retries': 'En çok {backward} referans isteği ve {forward} atıf yapan eser isteği · istek başına en çok {cap} atıf yapan eser · yeniden denemelerle birlikte en çok {attempts} deneme',
