  'Equations read by {name} · {n} matched to {p} page · check against the page': 'Denklemleri {name} okudu · {n} tanesi {p} sayfaya eşlendi · sayfayla karşılaştırın',
  'Equations read by {name} · {n} matched to {p} pages · check against the page': 'Denklemleri {name} okudu · {n} tanesi {p} sayfaya eşlendi · sayfayla karşılaştırın',
