  '{name}’s equations did not match the PDF’s text · none used': '{name} denklemleri PDF’in metniyle eşleşmedi · hiçbiri kullanılmadı',
  'Equations not read · {name} refused the key; nothing more is sent until the key or the default model changes': 'Denklemler okunmadı · {name} anahtarı reddetti; anahtar ya da varsayılan model değişene kadar başka bir şey gönderilmez',
  'Equations not read · the {name} request budget is used up': 'Denklemler okunmadı · {name} istek bütçesi tükendi',
  'Equations not read · {reason}': 'Denklemler okunmadı · {reason}',
  '{name} could not read the equations · {reason}': '{name} denklemleri okuyamadı · {reason}',
  'Equations read by Marker earlier (LaTeX) · {n} to check against the page': 'Denklemleri daha önce Marker okudu (LaTeX) · {n} tanesi sayfayla karşılaştırılmalı',
  'Equations read by Marker earlier (LaTeX) · {n} to check against the pages': 'Denklemleri daha önce Marker okudu (LaTeX) · {n} tanesi sayfalarla karşılaştırılmalı',
  'Equations read by Marker earlier (LaTeX)': 'Denklemleri daha önce Marker okudu (LaTeX)',
  'The equation reader could not start. Resume to answer from the PDFs’ text layer.': 'Denklem okuyucu başlatılamadı. Devam ederseniz cevap PDF’lerin metin katmanından yazılır.',
  'Page read from the page image (Marker, read earlier). Equations are LaTeX and tables are rebuilt as tables; check them against the PDF page.': 'Sayfa, daha önce Marker ile sayfa görüntüsünden okunmuştu. Denklemler LaTeX’tir, tablolar yeniden tablo olarak kuruldu; PDF sayfasıyla karşılaştırın.',
  'Page read from the page image (Marker, read earlier). {n} equation on this page does not match the PDF’s own text and may be misread; check it against the PDF page.': 'Sayfa, daha önce Marker ile sayfa görüntüsünden okunmuştu. Bu sayfadaki {n} denklem PDF’in kendi metniyle uyuşmuyor ve yanlış okunmuş olabilir; PDF sayfasıyla karşılaştırın.',
  'Page read from the page image (Marker, read earlier). {n} equations on this page do not match the PDF’s own text and may be misread; check them against the PDF page.': 'Sayfa, daha önce Marker ile sayfa görüntüsünden okunmuştu. Bu sayfadaki {n} denklem PDF’in kendi metniyle uyuşmuyor ve yanlış okunmuş olabilir; PDF sayfasıyla karşılaştırın.',
  'Equation ({a}) in this passage was read by {name} from the page image and matched to the PDF’s letters, scripts and signs. Check it against the page. The rest of this passage is the PDF’s own text.': 'Bu pasajdaki ({a}) denklemini {name} sayfa görüntüsünden okudu ve PDF’in harfleri, üst/alt simgeleri ve işaretleriyle eşledi. Sayfayla karşılaştırın. Pasajın geri kalanı PDF’in kendi metnidir.',
  'Equations {numbers} in this passage were read by {name} from the page image and matched to the PDF’s letters, scripts and signs. Check them against the page. The rest of this passage is the PDF’s own text.': 'Bu pasajdaki {numbers} denklemlerini {name} sayfa görüntüsünden okudu ve PDF’in harfleri, üst/alt simgeleri ve işaretleriyle eşledi. Sayfayla karşılaştırın. Pasajın geri kalanı PDF’in kendi metnidir.',
  'The page image {name} read equation ({n}) from': '{name} adlı okuyucunun ({n}) denklemini okuduğu sayfa görüntüsü',
  'equations read by {name}': 'denklemleri {name} okudu',
  'equations read from the page image': 'denklemler sayfa görüntüsünden okundu',
  'Equations are read by the answer model: images of equation areas cut from PDFs are sent to {connection}.': 'Denklemleri cevap modeli okuyor: PDF’lerden kesilen denklem alanlarının görüntüleri {connection} bağlantısına gönderilir.',
  'Equations not read yet': 'Denklemler henüz okunmadı',
  'Equations could not be read': 'Denklemler okunamadı',
  'Reading the equations of a PDF failed. Resume to answer from that PDF’s text layer.': 'Bir PDF’in denklemleri okunamadı. Devam ederseniz cevap o PDF’in metin katmanından yazılır.',
  'A PDF’s equations could not be stored while another run uses the same source. Resume when that run ends.': 'Aynı kaynağı kullanan başka bir çalışma sürdüğü için bir PDF’in denklemleri kaydedilemedi. O çalışma bitince devam edin.',
  '{n} equation on this page does not match the PDF’s own text and may be misread; check it against the PDF page.': 'Bu sayfadaki {n} denklem PDF’in kendi metniyle uyuşmuyor ve yanlış okunmuş olabilir; PDF sayfasıyla karşılaştırın.',
  '{n} equations on this page do not match the PDF’s own text and may be misread; check them against the PDF page.': 'Bu sayfadaki {n} denklem PDF’in kendi metniyle uyuşmuyor ve yanlış okunmuş olabilir; PDF sayfasıyla karşılaştırın.',
  // The arXiv source route (D104): equations matched to the page by their numbers from the authors' LaTeX.
  'Equations from the arXiv source (v{version}) · {n} matched to {p} page by its number': 'Denklemler arXiv kaynağından (v{version}) · {n} tanesi {p} sayfaya numarasıyla eşlendi',
  'Equations from the arXiv source (v{version}) · {n} matched to {p} pages by its number': 'Denklemler arXiv kaynağından (v{version}) · {n} tanesi {p} sayfaya numarasıyla eşlendi',
  'Equations from the arXiv source (v{version}) · {n} matched to {p} page by their numbers': 'Denklemler arXiv kaynağından (v{version}) · {n} tanesi {p} sayfaya numaralarıyla eşlendi',
  'Equations from the arXiv source (v{version}) · {n} matched to {p} pages by their numbers': 'Denklemler arXiv kaynağından (v{version}) · {n} tanesi {p} sayfaya numaralarıyla eşlendi',
  'arXiv source not received yet · tried {n} times · next try after {time}': 'arXiv kaynağı henüz alınamadı · {n} kez denendi · sonraki deneme {time} sonrası',
  'No equations from the arXiv source · {reason}': 'arXiv kaynağından denklem yok · {reason}',
  'Equations from the arXiv source could not be used · {reason}': 'arXiv kaynağından denklemler kullanılamadı · {reason}',
