  'Monthly budget saved.': 'Aylık bütçe kaydedildi.',
  'Mathpix reads the numbered equations in your PDFs from an image of the page. DEIXIS keeps an equation only when its letters, scripts and signs match the PDF’s own text.': 'Mathpix, PDF’lerinizdeki numaralı denklemleri sayfanın görüntüsünden okur. DEIXIS bir denklemi yalnızca harfleri, üst/alt simgeleri ve işaretleri PDF’in kendi metniyle eşleştiğinde tutar.',
  'Runs on Mathpix’s servers': 'Mathpix’in sunucularında çalışır',
  'Needs your own Mathpix key pair': 'Kendi Mathpix anahtar çiftiniz gerekir',
  'DEIXIS does not send the PDF or its extracted text. For each numbered equation it sends an image of the area it takes to be the equation; that area can hold nearby content.': 'DEIXIS PDF’i ya da çıkarılan metnini göndermez. Her numaralı denklem için denklem saydığı alanın görüntüsünü gönderir; bu alan yakındaki içeriği de kapsayabilir.',
