  'App key': 'Uygulama anahtarı',
  'A new pair is tested with Mathpix’s usage API before it is saved. The test shows that Mathpix accepted the pair, not that the account has credit for reading images.': 'Yeni bir çift kaydedilmeden önce Mathpix’in kullanım API’siyle denenir. Deneme, Mathpix’in çifti kabul ettiğini gösterir; hesabın görüntü okumak için kredisi olduğunu göstermez.',
  'Remove key pair': 'Anahtar çiftini kaldır',
  'Remove the Mathpix key pair? No new request is sent; equations already read stay in the stored text.': 'Mathpix anahtar çifti kaldırılsın mı? Yeni istek gönderilmez; okunmuş denklemler kayıtlı metinde kalır.',
