  'DEIXIS has not measured how often Mathpix misreads an equation. An equation whose letters, scripts or signs differ from the PDF’s text is not used, but a misread that keeps all of them, such as a wrong digit, can pass. Check equations against the page.': 'DEIXIS, Mathpix’in bir denklemi ne sıklıkla yanlış okuduğunu ölçmedi. Harfleri, üst/alt simgeleri ya da işaretleri PDF’in metninden farklı olan denklem kullanılmaz; ancak hepsini koruyan bir yanlış okuma, örneğin yanlış bir rakam, geçebilir. Denklemleri sayfayla karşılaştırın.',
