  'Version': 'Sürüm',
  'Path': 'Konum',
  'Role': 'Rol',
  'DEIXIS only checks whether this tool is installed; it never uses it for research.': 'DEIXIS yalnızca bu aracın kurulu olup olmadığına bakar; araştırma için onu hiç kullanmaz.',
  'Uses the GitHub account you are signed in with in Copilot CLI. DEIXIS keeps no password or token of its own.': 'Copilot CLI’da oturum açtığınız GitHub hesabını kullanır. DEIXIS kendine ait parola ya da belirteç saklamaz.',
  'Copilot CLI only writes text for DEIXIS: its tools, add-ons and instruction files are turned off. Each model uses your Copilot plan’s requests at the rate GitHub sets for it.': 'Copilot CLI DEIXIS için yalnızca metin yazar: araçları, eklentileri ve talimat dosyaları kapalıdır. Her model, Copilot planınızın isteklerini GitHub’ın o model için belirlediği oranda kullanır.',
  'Gemini CLI only writes text for DEIXIS: DEIXIS starts it with its own settings, which turn off its tools, MCP servers, extensions and instruction files, and stops a step if the CLI reports any tool use.': 'Gemini CLI, DEIXIS için yalnızca metin yazar: DEIXIS onu araçlarını, MCP sunucularını, eklentilerini ve talimat dosyalarını kapatan kendi ayarlarıyla başlatır ve CLI herhangi bir araç kullanımı bildirirse adımı durdurur.',
  'Gemini CLI cannot list its models, so this list is fixed in DEIXIS. A step that another model answers is stopped.': 'Gemini CLI modellerini listeleyemez; bu yüzden bu liste DEIXIS’te sabittir. Başka bir modelin yanıtladığı adım durdurulur.',
  'Uses the Google account you are signed in with in Gemini CLI. DEIXIS keeps no password or token of its own.': 'Gemini CLI’da oturum açtığınız Google hesabını kullanır. DEIXIS kendine ait parola veya belirteç tutmaz.',
  'DEIXIS talks to {name} directly with your key. This connection has not been tested with the real {name} service yet.': 'DEIXIS, anahtarınızla doğrudan {name} hizmetine bağlanır. Bu bağlantı gerçek {name} hizmetiyle henüz denenmedi.',
  'Not responding: it did not answer its version check within 5 seconds.': 'Yanıt vermiyor: sürüm denetimine 5 saniye içinde cevap vermedi.',
  'Detected only; it does not run steps': 'Yalnızca algılanır; adımları çalıştırmaz',
  'Imports a collection into a research, read-only': 'Bir koleksiyonu araştırmaya salt okunur aktarır',
  'Not answering. Open Zotero and close any dialog it shows, then turn on Settings → Advanced → “Allow other applications on this computer to communicate with Zotero”.': 'Cevap vermiyor. Zotero’yu açın ve açık bir pencere varsa kapatın; sonra Ayarlar → Gelişmiş → “Bu bilgisayardaki diğer uygulamaların Zotero ile iletişim kurmasına izin ver” seçeneğini açın.',
  'Local API on · {endpoint}': 'Yerel API açık · {endpoint}',
  'Running, but its local API is off. Turn on Settings → Advanced → “Allow other applications on this computer to communicate with Zotero”.': 'Çalışıyor ama yerel API kapalı. Ayarlar → Gelişmiş → “Bu bilgisayardaki diğer uygulamaların Zotero ile iletişim kurmasına izin ver” seçeneğini açın.',
