  '{file} will be read in later answers and cells instead of the current file. The current file is not deleted: evidence that cites it keeps opening it.': 'Sonraki yanıt ve hücrelerde mevcut dosya yerine {file} okunacak. Mevcut dosya silinmez: ona dayanan kanıt onu açmaya devam eder.',
