  'The OCR text could not be stored while another run uses the same source. Resume when that run ends.': 'Aynı kaynağı kullanan başka bir çalışma sürerken OCR metni kaydedilemedi. O çalışma bitince devam edin.',
  'The PDF’s pages without text changed while OCR was running. Nothing was stored; start OCR again.': 'OCR sürerken PDF’in metinsiz sayfaları değişti. Hiçbir şey kaydedilmedi; OCR’ı yeniden başlatın.',
