  'The quote could not be marked exactly in the text of {locator}, so nothing is marked. Check the page in the PDF.': 'Alıntı {locator} metninde tam olarak işaretlenemedi, bu yüzden hiçbir şey işaretlenmedi. Sayfayı PDF’te denetleyin.',
