  'Incomplete: code and model runs did the screening, and you looked only at your queue and the audit sample. The counts are not added up.': 'Eksik: taramayı kod ve model koşuları yaptı, siz yalnızca kuyruğunuza ve denetim örneğine baktınız. Sayılar toplanmaz.',
