  'Of your {n} decision, you changed a decision of code or the model runs in {m} (code {code}, model runs {model}).': '{n} kararınızın {m} tanesinde kodun ya da model koşularının kararını değiştirdiniz (kod {code}, model koşuları {model}).',
  'Of your {n} decisions, you changed a decision of code or the model runs in {m} (code {code}, model runs {model}).': '{n} kararınızın {m} tanesinde kodun ya da model koşularının kararını değiştirdiniz (kod {code}, model koşuları {model}).',
  'This audit row changed after it was shown; its current state is loaded. Nothing was saved.': 'Bu denetim satırı gösterildikten sonra değişti; güncel hâli yüklendi. Hiçbir şey kaydedilmedi.',
