  // Slice 21: the built-in embedding model, the English sentence, the free-tier and uploaded-PDF lines.
  'This computer · built-in': 'Bu bilgisayarda · yerleşik',
  'Voyage AI embeddings': 'Voyage AI gömmeleri',
  '{model} · sends titles, abstracts and passage text to Voyage AI': '{model} · başlıkları, özetleri ve pasaj metnini Voyage AI’a gönderir',
  'Semantic search and reranking with Voyage stop until you add a key again.': 'Voyage ile anlamsal arama ve yeniden sıralama, yeniden bir anahtar ekleyene kadar durur.',
  'Needs a Voyage AI key': 'Voyage AI anahtarı gerekli',
  'Add a Voyage API key': 'Bir Voyage API anahtarı ekleyin',
  'The question, titles, abstracts and passage text are sent to {service}. Each run records the tokens Voyage counted.': 'Soru, başlıklar, özetler ve pasaj metni {service}’a gönderilir. Her çalıştırma Voyage’ın saydığı token sayısını kaydeder.',
  'Reranking setting saved.': 'Yeniden sıralama ayarı kaydedildi.',
  'Search & ranking': 'Arama ve sıralama',
  'Language models': 'Dil modelleri',
  'Tools that take the text out of PDFs.': 'PDF’lerin metnini çıkaran araçlar.',
  'Reranking the first records (reranker)': 'İlk kayıtları yeniden sıralama (yeniden sıralayıcı)',
  'Reranking': 'Yeniden sıralama',
  'Reorders the top of the ranking by reading the question with each title and abstract, before records are read, so it decides which papers fall within the reading limit. Only the record order is reranked; passages for answers are not. A reranker score never includes or excludes a record, and records you included stay first.': 'Kayıtlar okunmadan önce, soruyu her başlık ve özetle birlikte okuyarak sıralamanın üst kısmını yeniden sıralar; böylece hangi makalelerin okuma sınırına gireceğine o karar verir. Yalnızca kayıt sırası yeniden sıralanır; yanıtlar için pasajlar değil. Yeniden sıralama puanı hiçbir kaydı dahil etmez ya da dışlamaz; sizin dahil ettiğiniz kayıtlar başta kalır.',
  'Reranker': 'Yeniden sıralayıcı',
  'The fused ranking is read as it is.': 'Birleştirilmiş sıralama olduğu gibi okunur.',
  'Voyage AI reranker': 'Voyage AI yeniden sıralayıcı',
  '{model} · sends the question and titles and abstracts to {service}': '{model} · soruyu, başlıkları ve özetleri {service} hizmetine gönderir',
  'Advanced': 'Gelişmiş',
  'Records reranked': 'Yeniden sıralanan kayıt',
  '{n}× (recommended)': '{n}× (önerilen)',
  '× the papers a run reads. On Standard, 200 records are reranked for 50 read.': 'Okunan makale sayısının katı. Standart’ta 50 okunan için 200 kayıt sıralanır.',
  'Time limit': 'Süre sınırı',
  's': 'sn',
  'When the reranker fails or runs out of time, the run keeps the fused order and says so; no other reranker is used.': 'Yeniden sıralayıcı başarısız olursa ya da süresi dolarsa çalıştırma birleştirilmiş sırayı korur ve bunu belirtir; başka bir yeniden sıralayıcı kullanılmaz.',
  'The question and the title and abstract of each reranked record, to Voyage AI': 'Soru ile yeniden sıralanan her kaydın başlığı ve özeti Voyage AI’a gönderilir',
  'Checking that the model starts and answers…': 'Modelin açılıp yanıt verdiği denetleniyor…',
  'Update': 'Güncelle',
