  // The built-in models on llama.cpp: a catalog card per model, its sheet and the earlier PyTorch install.
  'After that, it runs on this computer and sends no text off it.': 'Bundan sonra bu bilgisayarda çalışır ve dışarıya hiç metin göndermez.',
