  'Earlier built-in model (PyTorch) · {size}': 'Önceki yerleşik model (PyTorch) · {size}',
  'File': 'Dosya',
  'Files checked at install and with Check files.': 'Dosyalar kurulumda ve “Dosyaları denetle” ile denetlenir.',
  'Files checked {time}, at install and with Check files.': 'Dosyalar denetlendi: {time}; kurulumda ve “Dosyaları denetle” ile denetlenir.',
  'Its file is deleted. Scores it already gave are kept; sources not yet scored are ranked without it until you download it again.': 'Dosyası silinir. Verdiği puanlar korunur; henüz puanlanmamış kaynaklar siz yeniden indirene kadar onsuz sıralanır.',
  'May not fit in this computer’s {memory} GB of memory': 'Bu bilgisayarın {memory} GB belleğine sığmayabilir',
