  'Not available on this platform': 'Bu platformda yok',
  'Picked from this computer’s memory by a starting rule, not measured.': 'Bu bilgisayarın belleğine göre bir başlangıç kuralıyla seçildi; ölçülmedi.',
  'Recommended for this computer': 'Bu bilgisayar için önerilen',
  'Recommended for this computer: {model}, about {size} of disk.': 'Bu bilgisayar için önerilen: {model}, yaklaşık {size} disk.',
  'Remove the earlier built-in model?': 'Önceki yerleşik model kaldırılsın mı?',
  'Runtime': 'Çalıştırıcı',
  'Size': 'Boyut',
  'The PyTorch model files and the Python environment the earlier version of DEIXIS used are deleted ({size}). The current built-in models do not use them. Scores it already gave are kept.': 'DEIXIS’in önceki sürümünün kullandığı PyTorch model dosyaları ve Python ortamı silinir ({size}). Şimdiki yerleşik modeller bunları kullanmaz. Verdiği puanlar korunur.',
  'The built-in model chosen earlier is not available in this version of DEIXIS, so semantic search does not run with it. Pick a built-in model below; DEIXIS does not switch to another one by itself. Scores stored with the earlier model are kept but not reused.': 'Daha önce seçilen yerleşik model DEIXIS’in bu sürümünde yok, bu yüzden anlamsal arama onunla çalışmaz. Aşağıdan bir yerleşik model seçin; DEIXIS kendiliğinden başka birine geçmez. Önceki modelle kaydedilen puanlar saklanır ama yeniden kullanılmaz.',
  'The built-in models are not available on this platform yet.': 'Yerleşik modeller bu platformda henüz yok.',
  'The built-in reranker chosen earlier is not available in this version of DEIXIS. Pick a reranker below; DEIXIS does not switch to another one by itself.': 'Daha önce seçilen yerleşik yeniden sıralayıcı DEIXIS’in bu sürümünde yok. Aşağıdan bir yeniden sıralayıcı seçin; DEIXIS kendiliğinden başka birine geçmez.',
  'The earlier built-in model was removed.': 'Önceki yerleşik model kaldırıldı.',
  'The file is in place but has not been checked yet. Check files reads it in full.': 'Dosya yerinde ama henüz denetlenmedi. “Dosyaları denetle” onu baştan sona okur.',
  'The last download failed. Settings → Search & ranking shows the details.': 'Son indirme başarısız oldu. Ayrıntılar Ayarlar → Arama ve sıralama’da.',
  'The model file ({size}) is downloaded once from Hugging Face into the DEIXIS data folder.': 'Model dosyası ({size}) Hugging Face’ten bir kez DEIXIS veri klasörüne indirilir.',
