  'Passage text is sent to Google. If your key is on Google’s free tier, which DEIXIS cannot detect, Google may use that text to improve its products.': 'Pasaj metni Google’a gönderilir. Anahtarınız Google’ın ücretsiz katmanındaysa (DEIXIS bunu göremez) Google bu metni ürünlerini geliştirmek için kullanabilir.',
  'For semantic search, no text leaves the computer.': 'Anlamsal aramada hiçbir metin bilgisayardan çıkmaz.',
