  'Screen more queued: {n} work is read twice at the abstract stage. It never includes a source by itself.': 'Daha fazla tarama sıraya alındı: {n} eser özet aşamasında iki kez okunur. Tek başına hiçbir kaynağı dahil etmez.',
  'Screen more queued: {n} works are read twice at the abstract stage. It never includes a source by itself.': 'Daha fazla tarama sıraya alındı: {n} eser özet aşamasında iki kez okunur. Tek başına hiçbir kaynağı dahil etmez.',
  'Another run of this research is active, so Screen more was not queued.': 'Bu araştırmanın başka bir koşusu çalışıyor; bu yüzden daha fazla tarama sıraya alınmadı.',
  'No work with an abstract is left on the ranked list, so Screen more was not queued.': 'Sıralı listede özeti olan eser kalmadı; bu yüzden daha fazla tarama sıraya alınmadı.',
  'This research has no completed search with a ranked list, so Screen more was not queued.': 'Bu araştırmanın sıralı listesi olan tamamlanmış bir araması yok; bu yüzden daha fazla tarama sıraya alınmadı.',
  'Found by search and citations': 'Arama ve atıflarla bulunan',
  '{keyword} from the searches ({rows} records returned), {chained} only from citation chaining; duplicates merged by DOI.': '{keyword} aramalardan ({rows} kayıt döndü), {chained} yalnızca atıf zincirinden; yinelenenler DOI ile birleştirildi.',
  '{rows} records returned by the searches, merged by DOI into these works.': 'Aramaların döndürdüğü {rows} kayıt, DOI ile bu eserlerde birleştirildi.',
  'Works a model read at the abstract stage. {depth} depth reads the top {n} of the ranked list.': 'Bir modelin özet aşamasında okuduğu eserler. {depth} derinlik sıralı listenin ilk {n} eserini okur.',
  'Works a model read at the abstract stage.': 'Bir modelin özet aşamasında okuduğu eserler.',
  'never screened': 'hiç taranmadı',
  'Show them': 'Göster',
  'Screen {n} more': '{n} tane daha tara',
  'Works whose current abstract-stage decision is that they may meet the criterion. An abstract alone never includes a work.': 'Güncel özet aşaması kararı ölçütü karşılayabilecekleri yönünde olan eserler. Özet tek başına hiçbir eseri dahil etmez.',
  'Works whose two full-text passes both stored a result in one run. Each pass reads selected pages of the PDF, not the whole text. Reading the full text, or your own decision, is what includes a work.': 'Tek bir koşuda iki tam metin okumasının da sonuç kaydettiği eserler. Her okuma PDF\'nin tamamını değil, seçilmiş sayfalarını okur. Bir eseri dahil eden, tam metnin okunması ya da sizin kararınızdır.',
