  'You moved the {role} role from {from} to {to} ({time}). The finished steps keep their model; the stopped step uses the new one when you retry it.': '{role} rolünü {from} modelinden {to} modeline taşıdınız ({time}). Biten adımlar modellerini korur; duran adım, yeniden denediğinizde yenisini kullanır.',
  'Not read': 'Okunmadı',
  'Not known: the never-screened list is not read': 'Bilinmiyor: hiç taranmamış eserler listesi okunmadı',
  'The next works could not be read.': 'Sonraki eserler okunamadı.',
  'Reading the works found but never screened…': 'Bulunan ama hiç taranmamış eserler okunuyor…',
  'This research has no completed search with a ranked list, so no work is listed as never screened.': 'Bu araştırmanın sıralı listesi olan tamamlanmış bir araması yok, bu yüzden hiç taranmamış olarak listelenen eser yok.',
  'The works found but never screened could not be read.': 'Bulunan ama hiç taranmamış eserler okunamadı.',
  'These works were found but never screened: {depth} depth screens the top {n} of the ranked list. {total} works sit below that line, listed here in its order; {screenable} of them have an abstract to read.': 'Bu eserler bulundu ama hiç taranmadı: {depth} derinlik sıralı listenin ilk {n} eserini tarar. {total} eser bu çizginin altında kalıyor ve burada listenin sırasıyla gösteriliyor; {screenable} tanesinin okunacak özeti var.',
  'These works were found but never screened. {total} works sit below the part of the ranked list that was screened, listed here in its order; {screenable} of them have an abstract to read.': 'Bu eserler bulundu ama hiç taranmadı. {total} eser sıralı listenin taranan kısmının altında kalıyor ve burada listenin sırasıyla gösteriliyor; {screenable} tanesinin okunacak özeti var.',
  'Rank and similarity are the signals the list was ordered by, not relevance.': 'Sıra ve benzerlik, listenin sıralandığı sinyallerdir; ilgililik değildir.',
  'Reads the abstracts of the next {n} works twice; it never includes a source by itself.': 'Sonraki {n} eserin özetlerini iki kez okur; hiçbir kaynağı kendi başına dahil etmez.',
  'Recheck of “{column}” started: {n} cell is read again. Its result will wait as a proposal.': '“{column}” yeniden denetimi başladı: {n} hücre yeniden okunuyor. Sonucu öneri olarak bekleyecek.',
  'Recheck of “{column}” started: {n} cells are read again. Their results will wait as proposals.': '“{column}” yeniden denetimi başladı: {n} hücre yeniden okunuyor. Sonuçları öneri olarak bekleyecek.',
  '{n} row has no stored text and gets no call.': '{n} satırın kayıtlı metni yok ve ona çağrı yapılmaz.',
  '{n} rows have no stored text and get no call.': '{n} satırın kayıtlı metni yok ve onlara çağrı yapılmaz.',
  '{column}: {done} / {n} cells': '{column}: {done} / {n} hücre',
  'Each row with stored text is read again for this column; every result waits as a proposal, and the model does not see the current values.': 'Kayıtlı metni olan her satır bu sütun için yeniden okunur; her sonuç öneri olarak bekler ve model mevcut değerleri görmez.',
  'Recheck this column': 'Bu sütunu yeniden denetle',
  '{n} row · 1–2 calls · {model}': '{n} satır · 1–2 çağrı · {model}',
  '{n} rows · 1–2 calls each · {model}': '{n} satır · her biri 1–2 çağrı · {model}',
  'Column recheck finished. Its results wait as proposals in the cells; no value was changed.': 'Sütun yeniden denetimi bitti. Sonuçları hücrelerde öneri olarak bekliyor; hiçbir değer değiştirilmedi.',
  'Column recheck': 'Sütun yeniden denetimi',
  'Rechecking a column': 'Bir sütun yeniden denetleniyor',
  'The column left the table before its recheck finished. Proposals already written stay in their cells.': 'Sütun, yeniden denetimi bitmeden tablodan çıktı. Zaten yazılmış öneriler hücrelerinde kalır.',
  // UI parity S27, Sol round 1: models named from stored sessions, a stopped review asked again on another model.
  '{role}, set for the next calls': '{role}, sonraki çağrılar için seçili',
  'You moved the {role} role from {from} to {to} ({time}). A review by another model keeps the model it was requested with, so Retry sends it to {model} again.': '{role} rolünü {from} modelinden {to} modeline taşıdınız ({time}). Başka bir modelle inceleme, istendiği modelde kalır; Yeniden dene onu yine {model} modeline gönderir.',
  'the same model': 'aynı model',
  'You moved the {role} role from {from} to {to} ({time}). The stopped step runs on the {stopped} model, so Retry sends it where it went before.': '{role} rolünü {from} modelinden {to} modeline taşıdınız ({time}). Duran adım {stopped} modelinde çalışır; Yeniden dene onu önceki yerine gönderir.',
  'Review again with another model': 'Başka bir modelle yeniden incele',
  'Not changed: {message}. The latest state could not be read; reload the page.': 'Değiştirilmedi: {message}. Son durum okunamadı; sayfayı yeniden yükleyin.',
  'A new review started on {model}. The stopped review keeps {old} and stays as it was.': '{model} ile yeni bir inceleme başladı. Duran inceleme {old} modelinde ve olduğu gibi kalır.',
  'A new review started. The stopped review keeps its model and stays as it was.': 'Yeni bir inceleme başladı. Duran inceleme kendi modelinde ve olduğu gibi kalır.',
  'This review keeps the model it was requested with ({model}); Retry sends it there again. Start review begins a new review of the same target on the model you choose, with the same focus and note; the stopped review stays as it is.': 'Bu inceleme istendiği modelde kalır ({model}); Yeniden dene onu yine oraya gönderir. İncelemeyi başlat, aynı hedefin yeni bir incelemesini seçtiğiniz modelde, aynı odak ve notla başlatır; duran inceleme olduğu gibi kalır.',
  'The stopped review could not be read: {error}': 'Duran inceleme okunamadı: {error}',
  'Reading the stopped review…': 'Duran inceleme okunuyor…',
  'The never-screened works keep the ranked list’s stored order; sorting does not apply to them.': 'Hiç taranmamış eserler sıralı listenin kayıtlı sırasını korur; sıralama onlara uygulanmaz.',
  'Ranked list order': 'Sıralı liste düzeni',
  'Later steps of the role you pick use the model you choose; the stopped step uses it on Retry only when it is a step of that role. Steps that already finished keep the model they ran on, and nothing is sent until you retry the step.': 'Seçtiğiniz rolün sonraki adımları seçtiğiniz modeli kullanır; duran adım onu Yeniden dene ile yalnızca o rolün adımıysa kullanır. Bitmiş adımlar çalıştıkları modeli korur ve adımı yeniden denemedikçe hiçbir şey gönderilmez.',
  '{role} model changed from {from} to {to} for this research. Later steps of that role use it; the stopped step is a {stopped} step, so Retry still sends it to the {stopped} model.': '{role} modeli bu araştırma için {from} modelinden {to} modeline değişti. O rolün sonraki adımları onu kullanır; duran adım bir {stopped} adımı olduğundan Yeniden dene onu yine {stopped} modeline gönderir.',
  'No unscreened works left to list.': 'Listelenecek taranmamış eser kalmadı.',
