  'Publisher links open through this address in your browser, and DEIXIS never stores your library password. Test saves the address and checks once that the proxy answers; it does not open an article.': 'Yayıncı bağlantıları tarayıcınızda bu adres üzerinden açılır; DEIXIS kütüphane parolanızı asla saklamaz. Dene, adresi kaydeder ve proxy’nin cevap verip vermediğine bir kez bakar; makale açmaz.',
  '{p}% of budget': 'bütçenin %{p} kadarı',
  '${x} left today': 'bugün ${x} kaldı',
  'Usage this month': 'Bu ayki kullanım',
