  '{n} of them priced later from the {date} price list; the price was not known when they were made.': 'Bunların {n} tanesi sonradan {date} tarihli fiyat listesiyle fiyatlandı; çağrı yapıldığında fiyatı bilinmiyordu.',
  'Read from {name}, {time}': '{name} hesabından okundu, {time}',
  'Reported on the last call, {time}': 'Son çağrıda bildirildi, {time}',
  'On this computer, no charge': 'Bu bilgisayarda, ücretsiz',
  'Shown after the first call': 'İlk çağrıdan sonra görünür',
  'Limit not reported': 'Sınır bildirilmiyor',
  'Spending is estimated for models paid by API key, from {date}. A subscription shows its own limit: Codex is read when this page opens, Claude Code reports it with each call.': 'API anahtarıyla ödenen modellerde harcama {date} tarihinden beri tahmin edilir. Abonelikli modellerde sağlayıcının kendi sınırı gösterilir: Codex bu sayfa açılınca okunur, Claude Code her çağrıda bildirir.',
  'The OpenAlex figure is read from OpenAlex when this page opens.': 'OpenAlex rakamı bu sayfa açıldığında OpenAlex\'ten okunur.',
  'The OpenAlex figure comes from its last response, not a live reading.': 'OpenAlex rakamı canlı bir ölçüm değil, son cevabından alınır.',
  'Estimated spending': 'Tahmini harcama',
  'Estimated today': 'Bugünkü tahmin',
  'Models you pay for with an API key. Models on a subscription or on this computer cost nothing per call and are not counted.': 'API anahtarıyla ödediğiniz modeller. Abonelikle ya da bu bilgisayarda çalışan modellerin çağrı başına maliyeti yoktur, sayılmazlar.',
  'from {n} call': '{n} çağrıdan',
  'from {n} calls': '{n} çağrıdan',
  '{n} of them estimated from text length because the provider sent no usage': 'bunlardan {n} tanesi, sağlayıcı kullanım bilgisi göndermediği için metin uzunluğundan tahmin edildi',
  'Not counted: {n} calls on models with no listed price.': 'Sayılmadı: fiyatı listede olmayan modellerde {n} çağrı.',
  'Stop at an estimated amount per day': 'Günlük tahmini tutarda dur',
  'Off by default. A research pauses before its next paid call once today’s estimate reaches this amount.': 'Varsayılan olarak kapalı. Bugünkü tahmin bu tutara ulaşınca araştırma, ücretli bir sonraki çağrıdan önce duraklar.',
  'A call already sent finishes and is kept. Press Resume run to go on; raising the amount does not resume it. This is an estimate, not a limit.': 'Gönderilmiş bir çağrı biter ve saklanır. Devam etmek için İşleme devam et düğmesine basın; tutarı yükseltmek araştırmayı kendiliğinden başlatmaz. Bu bir tahmindir, kesin sınır değildir.',
  'Enter an amount in US dollars, for example 5.': 'ABD doları olarak bir tutar girin, örneğin 5.',
  'The spending threshold is off.': 'Harcama eşiği kapalı.',
  'The spending threshold is saved.': 'Harcama eşiği kaydedildi.',
  'Costs are estimated from the usage each provider reports and a price list dated {date}. The provider’s own bill is what counts.': 'Maliyetler, her sağlayıcının bildirdiği kullanımdan ve {date} tarihli bir fiyat listesinden tahmin edilir. Geçerli olan sağlayıcının kendi faturasıdır.',
  'under $0.01': '0,01 $’ın altında',
  'Today’s estimated spending reached your threshold, so this run paused before its next call.': 'Bugünkü tahmini harcama eşiğinize ulaştı, bu yüzden bu çalışma bir sonraki çağrıdan önce duraklatıldı.',
  'Today’s estimate is {spent}; your threshold is {limit}.': 'Bugünkü tahmin {spent}; eşiğiniz {limit}.',
  'The call that crossed it finished and is kept. To go on, raise or turn off the threshold in Settings, then press Resume run.': 'Eşiği aşan çağrı bitti ve saklandı. Devam etmek için Ayarlar’dan eşiği yükseltin ya da kapatın, sonra İşleme devam et düğmesine basın.',
  'Estimated cost: at least {low}, at most {high}.': 'Tahmini maliyet: en az {low}, en çok {high}.',
  'No cost estimate: DEIXIS has no price for this model.': 'Maliyet tahmini yok: DEIXIS’in bu model için fiyatı yok.',
  'Left out because no price is known: {models}.': 'Fiyatı bilinmediği için dışarıda bırakıldı: {models}.',
  'The provider’s own bill is what counts.': 'Geçerli olan sağlayıcının kendi faturasıdır.',
  'How this is estimated': 'Bu nasıl tahmin ediliyor',
  'Estimated cost': 'Tahmini maliyet',
  'Low: the fewest calls, the smallest inputs, no reasoning. High: every call this depth allows, the largest inputs, each call that can be repaired repaired once, and up to {n} tokens of reasoning per call.': 'Düşük: en az çağrı, en küçük girdiler, akıl yürütme yok. Yüksek: bu derinliğin izin verdiği tüm çağrılar, en büyük girdiler, onarılabilen her çağrının bir kez onarılması ve çağrı başına en çok {n} token akıl yürütme.',
  'Instruction sizes are measured; the length of abstracts, passages and answers is assumed ({n} characters per token). Cached input is priced as normal input. Price list dated {date}. Nothing was measured on a real run.': 'Yönergelerin boyutu ölçüldü; özetlerin, pasajların ve cevapların uzunluğu varsayıldı (token başına {n} karakter). Önbellekteki girdi normal girdi gibi fiyatlandı. Fiyat listesi {date} tarihli. Gerçek bir çalışmada ölçülmedi.',
  'Not included: semantic search on {provider}, billed separately, the study table and follow-up questions.': 'Dahil değil: {provider} üzerindeki anlamsal arama (ayrıca faturalanır), çalışma tablosu ve takip soruları.',
  'Not included: the study table and follow-up questions. Semantic search adds nothing here.': 'Dahil değil: çalışma tablosu ve takip soruları. Anlamsal arama buraya bir şey eklemez.',
  '{role} runs on {model}, a subscription: no cost per call.': '{role}, abonelikle çalışan {model} üzerinde: çağrı başına maliyet yok.',
  '{role} runs on {model} on this computer: no cost per call.': '{role}, bu bilgisayardaki {model} üzerinde: çağrı başına maliyet yok.',
  'Usage could not be read: {message}': 'Kullanım okunamadı: {message}',
