  'To import from zotero.org, create a read-only key at zotero.org/settings/keys. Your user ID is shown on the same page.': 'zotero.org’dan aktarmak için zotero.org/settings/keys adresinde salt okunur bir anahtar oluşturun. Kullanıcı kimliğiniz aynı sayfada yazar.',
  'zotero.org API key': 'zotero.org API anahtarı',
