  'Gemini CLI is signed in. DEIXIS cannot tell a new sign-in from the existing session.': 'Gemini CLI oturumu açık. DEIXIS yeni bir oturum açıldığını mevcut oturumdan ayırt edemez.',
  'The sign-in command ended with an error.': 'Oturum açma komutu bir hatayla bitti.',
  'The sign-in command finished, but the tool does not show a signed-in account yet.': 'Oturum açma komutu bitti, ancak araç henüz oturum açılmış bir hesap göstermiyor.',
  'Works without a key. A free key from openalex.org gives DEIXIS its own daily budget.': 'Anahtarsız da çalışır. openalex.org’dan alınan ücretsiz bir anahtar DEIXIS’e kendi günlük bütçesini verir.',
  'API key (optional, free from openalex.org)': 'API anahtarı (isteğe bağlı, openalex.org’dan ücretsiz)',
  'No key needed. DEIXIS adds your contact email to its requests, as the service asks.': 'Anahtar gerekmez. DEIXIS, hizmetin istediği gibi isteklerine iletişim e-postanızı ekler.',
  'No key needed.': 'Anahtar gerekmez.',
  'Get a key': 'Anahtar al',
  'Create a free account at openalex.org, then copy the key from Settings → API.': 'openalex.org’da ücretsiz bir hesap açın, anahtarı Settings → API sayfasından kopyalayın.',
  'bioRxiv uses the OpenAlex key. Create a free account at openalex.org, then copy the key from Settings → API.': 'bioRxiv, OpenAlex anahtarını kullanır. openalex.org’da ücretsiz bir hesap açın, anahtarı Settings → API sayfasından kopyalayın.',
  'Fill in the request form. The key arrives by email, which can take a few days.': 'İstek formunu doldurun. Anahtar e-postayla gelir; bu birkaç gün sürebilir.',
  'Sign in to the Elsevier Developer Portal and create a key. Scopus answers only through an institutional subscription, so the key works from your institution’s network.': 'Elsevier Developer Portal’a girip bir anahtar oluşturun. Scopus yalnızca kurum aboneliği üzerinden yanıt verir, bu yüzden anahtar kurumunuzun ağından çalışır.',
  'Sign in to an NCBI account, then open Account settings → API Key Management and choose Create.': 'Bir NCBI hesabıyla giriş yapın, Account settings → API Key Management bölümünü açıp Create’e basın.',
  'Register a developer account, then request a key for an application. Keys are sent during US business hours.': 'Bir geliştirici hesabı açın, sonra bir uygulama için anahtar isteyin. Anahtarlar ABD mesai saatlerinde gönderilir.',
  'Choose Register on the CORE API page and fill in the form. The key arrives by email.': 'CORE API sayfasında Register’a basıp formu doldurun. Anahtar e-postayla gelir.',
  'Sign up, then copy the key from the dashboard. The free plan allows 250 searches a month.': 'Kayıt olun, anahtarı panelden kopyalayın. Ücretsiz plan ayda 250 aramaya izin verir.',
  'Requests that need this key stop until you add one again.': 'Bu anahtarı gerektiren istekler, yeniden ekleyene kadar durur.',
  'DEIXIS uses Ollama on this computer, so no key is needed. Open the Ollama app or run `ollama serve`, then download a model with `ollama pull`.': 'DEIXIS bu bilgisayardaki Ollama’yı kullanır, bu yüzden anahtar gerekmez. Ollama uygulamasını açın ya da `ollama serve` çalıştırın, sonra `ollama pull` ile bir model indirin.',
