  'Adds the entries of a .bib or .ris file to the Library. Entries whose DOI OpenAlex or Crossref confirms use that record; the rest are kept as you wrote them, marked as not confirmed.': 'Bir .bib veya .ris dosyasındaki kayıtları Kütüphane’ye ekler. DOI’si OpenAlex veya Crossref tarafından doğrulanan kayıtlar o sağlayıcının kaydını kullanır; geri kalanlar yazdığınız gibi tutulur ve doğrulanmamış olarak işaretlenir.',
