  'Step 1 of 4 · Look up the bibliography': 'Adım 1 / 4 · Kaynakçayı ara',
  '{n} entries are not linked to a record yet. DEIXIS asks OpenAlex by DOI or arXiv id, else by a close title. No model is used.': '{n} girdi henüz bir kayda bağlı değil. DEIXIS OpenAlex’e DOI ya da arXiv kimliğiyle, yoksa yakın bir başlıkla sorar. Model kullanılmaz.',
