  'Wait for re-extraction: the PDFs of entries {entries} are being read again for their equations. A plan frozen now would go stale when that ends; this page checks again every few seconds.': 'Yeniden çıkarmayı bekleyin: {entries} numaralı girdilerin PDF\'leri denklemleri için yeniden okunuyor. Şimdi dondurulan plan bu iş bitince bayatlar; sayfa birkaç saniyede bir yeniden bakıyor.',
