  '{n} works are waiting. Works already checked are not sent again.': '{n} eser bekliyor. Kontrol edilmiş eserler yeniden gönderilmez.',
  '“Supports” is a model’s reading of the passages it was given, checked by code against their exact words. It is not scientific validation, and a statement no work supports here is not shown to be unsupported in the literature.': '“Destekliyor”, modelin kendisine verilen pasajları okumasıdır; kod bunu pasajların tam sözcükleriyle karşılaştırır. Bilimsel doğrulama değildir; burada hiçbir eserin desteklemediği bir iddianın literatürde desteksiz olduğu gösterilmiş olmaz.',
